-- Standalone: Bristol (race 3) predictions + feature importances.
-- Safe to re-run; replaces any existing Bristol rows.
begin;
update races set blend_note = '60% short-track season form / 40% Bristol Chase history' where chase_round = 3;

-- Josh Bilicki is in the Bristol entry list but wasn't in an earlier field
  on conflict (name) do nothing;

delete from predictions where race_id = (select id from races where chase_round = 3);
delete from feature_importances where race_id = (select id from races where chase_round = 3);


commit;
